-- Heart failure on problem list AND latest reported age >= 65 AND medicare coverage.
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('conditions','demographic_updates','coverage')), c AS (SELECT patient, json_extract(payload,'$.description') d, coalesce(json_extract(payload,'$.icd10'),'') i, coalesce(json_extract(payload,'$.snomed'),'') s FROM r WHERE stream='conditions'), du AS (SELECT patient, json_extract(payload,'$.age_reported') a, json_extract(payload,'$.age_reference_date') ad FROM r WHERE stream='demographic_updates'), demo AS (SELECT p.id patient, json_extract(p.payload,'$.sex_reported') sex, coalesce((SELECT a FROM du WHERE du.patient=p.id ORDER BY ad DESC LIMIT 1), json_extract(p.payload,'$.age_reported')) age FROM patients p), cov AS (SELECT patient, json_extract(payload,'$.coverage_type') ctype, json_extract(payload,'$.organization_id') payer FROM r WHERE stream='coverage')
SELECT COUNT(DISTINCT c.patient) AS count FROM c JOIN demo d ON d.patient=c.patient JOIN cov ON cov.patient=c.patient
WHERE (s='88805009' OR i LIKE 'I50%' OR lower(d) LIKE '%heart failure%' OR d LIKE '%CHF%') AND d.age >= 65 AND cov.ctype='medicare';
